const MAX_TIMEOUT = 30000; // Default timeout of 30 seconds
let currentRequest = null;

function executeLint(doc) {
    if (currentRequest) {
        currentRequest.abort();
    }

    const promise = new Promise((resolve, reject) => {
        currentRequest = mw.rest.post('/v1/transform/wikitext/to/lint', {
            wikitext: doc.toString()
        }).then(response => {
            resolve(response);
        }).catch(error => {
            reject(error);
        }).finally(() => {
            currentRequest = null;
        });
    });

    return Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), MAX_TIMEOUT))
    ]);
}

// Usage
executeLint(doc)
    .then(errors => {
        mw.log.info('[CodeMirror] Linting completed successfully.');
        // Handle errors
    })
    .catch(error => {
        mw.log.warn('[CodeMirror] Linting failed:', error.message);
        // Handle error
    });
```

